// The same closed optical domain is required during optimization and restart.
// A variable lens must not leave it and become an unusable accepted checkpoint.
class JointCaptureOpticalDomainCost final : public ceres::SizedCostFunction<1,12> {
 std::array<JointZoomCertificate,2> tests_;std::array<double,2> range_;std::vector<double> coupled_lower_,coupled_upper_;const EventParameterBlock*origin_=nullptr;std::string rig_id_;
 public:
 JointCaptureOpticalDomainCost(const JointRig& rig,const std::array<double,2>& range,const EventParameterBlock* box=nullptr,const EventParameterBlock* origin=nullptr):range_(range),origin_(origin?origin:box),rig_id_(rig.id){
  if(box){coupled_lower_=box->lower;coupled_upper_=box->upper;}
  for(int e=0;e<2;++e){auto& c=tests_[e];c.f_ref=rig.math.f_ref;c.radius=rig.math.radius_max;c.endpoint=e;c.wide_boundary=rig.math.wide_log_f_boundary;c.wide_coefficients=rig.math.wide_coefficients;}
 }
 bool Evaluate(double const*const* x,double* residual,double** jacobians)const override{
  // Coupled optical coordinates must be accepted or rejected together.
  // Independent ambient clipping destroys the feasible chart before Ceres can differentiate it.
  auto fail=[&](const char*why,int component,double value){return joint_actual_factor_failure_v1([&](eventio::Json&j){j["factor"]="capture_optical_domain";j["rig"]=rig_id_;j["failure_kind"]=why;j["component"]=component;j["value"]=joint_factor_failure_number_v1(value);j["log_f_range"]=range_;j["endpoint_g"]=eventio::Json::array();const double*p[]={x[0],range_.data()};for(const auto&c:tests_){double g=NAN;bool ok=c(p,&g);j["endpoint_g"].push_back({{"endpoint",c.endpoint},{"evaluated",ok},{"value",joint_factor_failure_number_v1(g)}});}append_joint_actual_failure_parameter_v1(j,origin_?origin_->values.data():nullptr,x[0],12,origin_?origin_->name:"rig/"+rig_id_+"/optics12");});};
  if(!coupled_lower_.empty())for(int j=5;j<=10;++j)if(!std::isfinite(x[0][j])||x[0][j]<coupled_lower_.at(j)||x[0][j]>coupled_upper_.at(j))return fail("coupled_optical_box",j,x[0][j]);
  const double* p[]={x[0],range_.data()};
  for(const auto& c:tests_){double g=0;if(!c(p,&g)||!std::isfinite(g)||g>0)return fail("Brown_certificate_endpoint",c.endpoint,g);}
  for(double z:range_)for(double sign:{-1.,1.})if(!std::isfinite(std::exp(z+sign*x[0][2]/2)))return fail("nonfinite_anisotropic_focal",2,x[0][2]);
  residual[0]=0.;if(jacobians&&jacobians[0])std::fill(jacobians[0],jacobians[0]+12,0.);return true;
 }
};
// Ceres ambient clipping of a linear-manifold block can leave its original
// subspace.  Evaluate these bounds after the real manifold Plus instead:
// lower <= e_i^T (x + N delta) <= upper.  Rejected trials cannot be accepted
// outside the certified zoom hull, and no ambient coordinate is clipped.
struct JointCaptureZoomBoundV1 { int index; double lower,upper; };
class JointCaptureAffineZoomDomainCost final : public ceres::CostFunction {
 std::vector<JointCaptureZoomBoundV1> bounds_;const EventParameterBlock*origin_;
 public:
 JointCaptureAffineZoomDomainCost(int size,std::vector<JointCaptureZoomBoundV1> bounds,const EventParameterBlock*origin=nullptr):bounds_(std::move(bounds)),origin_(origin){
  set_num_residuals(1);mutable_parameter_block_sizes()->push_back(size);
 }
 bool Evaluate(double const*const*x,double*r,double**j)const override{
  for(const auto&bound:bounds_)if(!std::isfinite(x[0][bound.index])||x[0][bound.index]<bound.lower||x[0][bound.index]>bound.upper)return joint_actual_factor_failure_v1([&](eventio::Json&record){record["factor"]="capture_affine_zoom_domain";record["component"]=bound.index;record["lower"]=bound.lower;record["upper"]=bound.upper;append_joint_actual_failure_parameter_v1(record,origin_?origin_->values.data():nullptr,x[0],parameter_block_sizes()[0],origin_?origin_->name:"affine_zoom");});
  r[0]=0.;if(j&&j[0])std::fill(j[0],j[0]+parameter_block_sizes()[0],0.);return true;
 }
};
inline eventio::Json install_joint_capture_zoom_bounds_v1(ceres::Problem&p,EventParameterBlock&v,
 const std::vector<int>&indices,const std::array<double,2>&range,bool affine,
 std::vector<ceres::ResidualBlockId>*registered_domain_blocks=nullptr){
 auto*x=v.values.data();if(!p.HasParameterBlock(x))throw std::runtime_error("authoritative zoom control missing from actual graph: "+v.name);
 std::vector<JointCaptureZoomBoundV1> bounds;eventio::Json report=eventio::Json::array();std::set<int>seen;
 for(int index:indices){if(!seen.insert(index).second)continue;
  const double lo=std::max(v.lower.at(index),range[0]),hi=std::min(v.upper.at(index),range[1]),value=v.values.at(index);
  if(!(lo<=hi)||!std::isfinite(value)||value<lo||value>hi)throw std::runtime_error("authoritative control logf outside existing certified domain; explicit feasibility restoration required: "+v.name+" index="+std::to_string(index)+" current="+std::to_string(value)+" range="+std::to_string(lo)+","+std::to_string(hi));
  bounds.push_back({index,lo,hi});
  if(!affine){p.SetParameterLowerBound(x,index,lo);p.SetParameterUpperBound(x,index,hi);if(p.GetParameterLowerBound(x,index)!=lo||p.GetParameterUpperBound(x,index)!=hi)throw std::runtime_error("actual Ceres logf bounds differ");}
  report.push_back({{"name",v.name},{"ambient_index",index},{"lower",lo},{"upper",hi},{"current",value},{"constant",p.IsParameterBlockConstant(x)},{"enforcement",affine?"linear_manifold_pullback_gate":"Ceres_scalar_bounds"}});
 }
 if(affine&&!bounds.empty()){const auto rid=p.AddResidualBlock(new JointCaptureAffineZoomDomainCost(int(v.values.size()),std::move(bounds),&v),nullptr,x);if(registered_domain_blocks)registered_domain_blocks->push_back(rid);}
 return report;
}
